#!/usr/bin/env node
/**
 * Generates the deployable, production-only HTML template from the checked-in
 * canonical visual source. The source includes authoring navigation/code panels
 * by design; this generator retains only its six legal `.page` sections and
 * turns visual field markers into semantic merge spans.
 *
 * Do not edit canonical-template.generated.ts directly. Update
 * templates/document-merge/trainee-registration/test.html, then run:
 *   node scripts/sync-trainee-registration-template.mjs
 */

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const sourcePath = join(ROOT, "templates", "document-merge", "trainee-registration", "test.html");
const outputPath = join(ROOT, "src", "document-templates", "dang-ky-tap-nghe", "canonical-template.generated.ts");
const migrationPath = join(ROOT, "migrations", "2026-08-23-trainee-registration-canonical-html-draft.sql");

// These are the exact checkbox semantic fields in the reviewed contract. They
// render as ☒/☐ via the existing CHECKBOX_OPTION resolver and base `.chk` CSS.
const CHECKBOX_PLACEHOLDERS = new Set([
  "Tien_an_tien_su_Khong", "Tien_an_tien_su_Co",
  "Da_tung_lam_DHF_Khong", "Da_tung_lam_DHF_Co",
  "Loai_cong_viec_Nhan_vien", "Loai_cong_viec_Cong_nhan", "Loai_cong_viec_Lao_dong_tap_nghe",
  "Khu_vuc_Da_Lat", "Khu_vuc_Da_Quy", "Khu_vuc_Da_Ron", "Khu_vuc_Lam_Ha", "Khu_vuc_Khac",
  "Cong_viec_hien_tai_Sinh_vien", "Cong_viec_hien_tai_Khac",
  "TKNH_Da_co", "TKNH_Chua_co",
  "Thu_nhap_Chi_DHF", "Thu_nhap_Ngoai_DHF",
  "Tap_nghe_Trong_cham_soc_thu_hoach", "Tap_nghe_Ban_hang", "Tap_nghe_Dong_goi", "Tap_nghe_Khac",
]);

function extractStyle(source) {
  const match = source.match(/<style\b[^>]*>([\s\S]*?)<\/style\s*>/i);
  if (!match) throw new Error("Canonical template is missing a <style> block.");
  return match[1].trim();
}

function classList(openTag) {
  const classMatch = openTag.match(/\bclass\s*=\s*(["'])(.*?)\1/i);
  return classMatch ? classMatch[2].trim().split(/\s+/) : [];
}

/** Return exact outer HTML for each top-level .page div, including its nested markup. */
function extractPageBlocks(source) {
  const pages = [];
  const opening = /<div\b[^>]*>/gi;
  let openMatch;
  while ((openMatch = opening.exec(source))) {
    if (!classList(openMatch[0]).includes("page")) continue;

    const tags = /<\/?div\b[^>]*>/gi;
    tags.lastIndex = openMatch.index;
    let depth = 0;
    let tag;
    while ((tag = tags.exec(source))) {
      if (/^<\/div\b/i.test(tag[0])) depth -= 1;
      else depth += 1;
      if (depth === 0) {
        pages.push(source.slice(openMatch.index, tags.lastIndex));
        break;
      }
    }
    if (depth !== 0) throw new Error(`Unclosed .page block beginning at byte ${openMatch.index}.`);
    opening.lastIndex = tags.lastIndex;
  }
  if (pages.length !== 6) throw new Error(`Expected exactly six canonical .page blocks; found ${pages.length}.`);
  return pages;
}

function semanticizeFieldMarkers(pageHtml) {
  return pageHtml.replace(
    /<span\s+class=(["'])f\1>\s*\{\{\s*([^{}]+?)\s*\}\}\s*<\/span>/g,
    (_whole, _quote, rawKey) => {
      const key = rawKey.trim();
      const className = CHECKBOX_PLACEHOLDERS.has(key) ? "chk" : "merge-value";
      return `<span class="${className}">{{${key}}}</span>`;
    },
  );
}

function asTemplateLiteral(value) {
  return value.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
}

const source = readFileSync(sourcePath, "utf8");
const html = extractPageBlocks(source).map(semanticizeFieldMarkers).join("\n\n");
const css = `${extractStyle(source)}

/* Production merge normalisation: strip editor styling, preserve exact A4 page geometry, and wrap long values safely. */
@media print {
  .page {
    box-shadow: none;
    margin: 0;
    width: 210mm;
    min-height: 297mm;
    height: 297mm;
    padding: 14mm 16mm;
    overflow: visible;
    break-after: page;
    page-break-after: always;
    break-inside: avoid;
    page-break-inside: avoid;
  }
  .page:last-child {
    break-after: auto;
    page-break-after: auto;
  }
  .photo-wrap .body-col { min-width: 0; }
  .merge-value {
    overflow-wrap: anywhere;
    word-break: normal;
  }
  .attach-box,
  .sign-single,
  .sign-3-table {
    break-inside: avoid;
    page-break-inside: avoid;
  }
}`;
const sourceHash = createHash("sha256").update(source).digest("hex");
const content = `/**
 * GENERATED FILE — do not edit directly.
 * Source: templates/document-merge/trainee-registration/test.html
 * Generated by: scripts/sync-trainee-registration-template.mjs
 *
 * The canonical source retains authoring-only controls. This production module
 * retains its six legal pages verbatim, apart from semantic field marker
 * conversion (.f → .merge-value/.chk).
 */

export const CANONICAL_TRAINEE_REGISTRATION_SOURCE_PATH = "templates/document-merge/trainee-registration/test.html";
export const CANONICAL_TRAINEE_REGISTRATION_SOURCE_SHA256 = "${sourceHash}";
export const CANONICAL_TRAINEE_REGISTRATION_LOGICAL_PAGE_COUNT = 6;

export const CANONICAL_TRAINEE_REGISTRATION_HTML = String.raw\`${asTemplateLiteral(html)}\`;

export const CANONICAL_TRAINEE_REGISTRATION_CSS = String.raw\`${asTemplateLiteral(css)}\`;
`;

const migration = `-- ============================================================
-- CANONICAL TRAINEE-REGISTRATION HTML — DRAFT ONLY
-- ------------------------------------------------------------
-- Source: templates/document-merge/trainee-registration/test.html
-- Source SHA-256: ${sourceHash}
--
-- This migration is idempotent and non-destructive. It adds one new DRAFT
-- version only; it does not publish, set current_published_version, change
-- html_enabled, create jobs, or activate HTML_PDF in any environment.
-- ============================================================
WITH target_template AS (
  SELECT id
  FROM merge_templates
  WHERE google_doc_id = '10D0tG71CbllIZe7DaosYNW3vK7QnP76Yq4UC9FMEiUE'
  ORDER BY created_at ASC
  LIMIT 1
), next_version AS (
  SELECT t.id AS template_id, COALESCE(MAX(v.version), 0) + 1 AS version
  FROM target_template t
  LEFT JOIN merge_template_versions v ON v.template_id = t.id
  GROUP BY t.id
)
INSERT INTO merge_template_versions (
  template_id, version, status, html_body, print_css, source_docx_name,
  retention_years, mapping_snapshot, created_by, created_at, updated_at
)
SELECT
  n.template_id,
  n.version,
  'DRAFT',
  $canonical_html$${html}$canonical_html$,
  $canonical_css$${css}$canonical_css$,
  'trainee-registration/test.html (canonical six-page HTML; preview UI stripped)',
  3,
  '[]'::jsonb,
  'system',
  now(),
  now()
FROM next_version n
WHERE NOT EXISTS (
  SELECT 1
  FROM merge_template_versions existing
  WHERE existing.template_id = n.template_id
    AND existing.source_docx_name = 'trainee-registration/test.html (canonical six-page HTML; preview UI stripped)'
);

-- Post-apply verification (read-only): must report one DRAFT, zero PUBLISHED.
SELECT version, status, source_docx_name
FROM merge_template_versions
WHERE source_docx_name = 'trainee-registration/test.html (canonical six-page HTML; preview UI stripped)';
`;

writeFileSync(outputPath, content, "utf8");
writeFileSync(migrationPath, migration, "utf8");
console.log(`Generated ${outputPath}`);
console.log(`Generated ${migrationPath}`);
console.log(`Canonical source SHA-256: ${sourceHash}`);
console.log(`Logical pages: ${extractPageBlocks(source).length}`);
